package com.viddown.app

import java.io.File
import java.io.IOException
import java.net.InetAddress
import java.net.ServerSocket
import java.net.Socket
import java.nio.ByteBuffer
import java.nio.ByteOrder
import kotlin.concurrent.thread

/** Media generated by the tests themselves (owned test data). */
object TestMedia {
    /** Mono 16-bit PCM sine wave in a WAV container. */
    fun wav(seconds: Double, rate: Int = 8000, hz: Double = 440.0): ByteArray {
        val samples = (seconds * rate).toInt()
        val data = ByteArray(samples * 2)
        for (i in 0 until samples) {
            val v = (Math.sin(2.0 * Math.PI * hz * i / rate) * 12000).toInt()
            data[2 * i] = (v and 0xff).toByte()
            data[2 * i + 1] = ((v shr 8) and 0xff).toByte()
        }
        val header = ByteBuffer.allocate(44).order(ByteOrder.LITTLE_ENDIAN)
        header.put("RIFF".toByteArray()).putInt(36 + data.size).put("WAVE".toByteArray())
        header.put("fmt ".toByteArray()).putInt(16).putShort(1).putShort(1).putInt(rate).putInt(rate * 2).putShort(2).putShort(16)
        header.put("data".toByteArray()).putInt(data.size)
        return header.array() + data
    }
}

/** Minimal HTTP/1.1 server on 127.0.0.1 serving fixed byte arrays. Supports GET and HEAD, no Range. */
class TestServer(private val routes: Map<String, Pair<String, ByteArray>>) : AutoCloseable {
    private val server = ServerSocket(0, 50, InetAddress.getByName("127.0.0.1"))

    @Volatile
    private var running = true

    val port: Int get() = server.localPort

    init {
        thread(isDaemon = true) {
            while (running) {
                val socket = try {
                    server.accept()
                } catch (e: Exception) {
                    break
                }
                thread(isDaemon = true) {
                    try {
                        handle(socket)
                    } catch (e: IOException) {
                        // the client (yt-dlp) closed the connection early; must not crash the instrumentation process
                    }
                }
            }
        }
    }

    private fun handle(socket: Socket) {
        socket.use { s ->
            val reader = s.getInputStream().bufferedReader(Charsets.ISO_8859_1)
            val requestLine = reader.readLine() ?: return
            val parts = requestLine.split(" ")
            val method = parts[0]
            val path = parts.getOrElse(1) { "/" }
            while (true) {
                val header = reader.readLine() ?: break
                if (header.isEmpty()) break
            }
            val out = s.getOutputStream()
            val route = routes[path]
            if (route == null) {
                out.write("HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n".toByteArray())
                out.flush()
                return
            }
            val (type, body) = route
            out.write("HTTP/1.1 200 OK\r\nContent-Type: $type\r\nContent-Length: ${body.size}\r\nConnection: close\r\n\r\n".toByteArray())
            if (method != "HEAD") out.write(body)
            out.flush()
        }
    }

    override fun close() {
        running = false
        try {
            server.close()
        } catch (e: Exception) {
            // already closed
        }
    }
}

fun File.deleteQuietly() {
    try {
        deleteRecursively()
    } catch (e: Exception) {
        // ignore
    }
}
